// План specs/admin-access.md, 1.2 (кейс AA-02). Пользователь «בדיקה», иврит. Только чтение. @prod-safe
import { test, expect } from '@playwright/test';
import { setLanguage } from '../admin-plans/plans-helpers';
import { DASHBOARD_URL, expectNoSupportConsole } from './access-helpers';

test.use({ storageState: '../auth/user.json' });

test.describe('Support Console — доступ обычного пользователя (#09773471)', () => {
  test('Non-admin opening /supportinbox is redirected to the dashboard without "אין גישה" (HE) #09773471 @desktop @prod-safe', async ({ page }) => {
    await setLanguage(page, 'he');

    await page.goto('/supportinbox');
    await expect(page).toHaveURL(DASHBOARD_URL);
    await expect(page.getByText('אין גישה')).toHaveCount(0);
    await expect(page.getByText('רק צוות התמיכה יכול לגשת לממשק התמיכה.')).toHaveCount(0);
    await expectNoSupportConsole(page);
  });
});
